import MainDashboardSuper from "views/rektor/default";
import RektorProfile from "views/rektor/profile";
import RektorUsers from "views/rektor/users";
import { Student } from "../views/rektor/student";
import { Month } from "../views/rektor/month";
import { MonthDetail } from "../views/rektor/month/MonthDetail"
import RejaTekshirish from "views/shared/reja-tekshirish";
import Statistics from "views/shared/statistics";

import {
  MdHome,
  MdPerson,
  MdGroup,
  MdOutlineCalendarToday,
  MdSchool,
  MdAssignmentTurnedIn,
  MdBarChart,
} from "react-icons/md";

const routes = [
  {
    name: "Bosh sahifa",
    layout: "/rektor",
    path: "default",
    icon: <MdHome className="h-6 w-6" />,
    component: <MainDashboardSuper />,
  },
  {
    name: "Xodimlar",
    layout: "/rektor",
    path: "users",
    icon: <MdGroup className="h-6 w-6" />,
    component: <RektorUsers />,
  },
  {
    name: "Doktorantlar",
    layout: "/rektor",
    path: "students",
    icon: <MdSchool className="h-6 w-6" />,
    component: <Student />,
  },
  {
    name: "Oy Yaratish",
    layout: "/rektor",
    path: "month",
    icon: <MdOutlineCalendarToday className="h-6 w-6" />,
    component: <Month />,
  },
  {
    name: "Hisobot ko'rish",
    layout: "/rektor",
    path: "statistics",
    icon: <MdBarChart className="h-6 w-6" />,
    component: <Statistics />,
  },
  {
    name: "Oy detail",
    layout: "/rektor",
    path: "month/:monthId",
    icon: <MdOutlineCalendarToday className="h-6 w-6" />,
    component: <MonthDetail />,
    hidden: true,
  },
  {
    name: "Reja tekshirish",
    layout: "/rektor",
    path: "reja-tekshirish",
    icon: <MdAssignmentTurnedIn className="h-6 w-6" />,
    component: <RejaTekshirish />,
  },

  {
    name: "Profile",
    layout: "/rektor",
    path: "profile",
    icon: <MdPerson className="h-6 w-6" />,
    component: <RektorProfile />,
  },
];
export default routes;
